<?php $pageTitle='Session History';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';$db=getDB();$club=$_SESSION['club_id'];$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$export=$_GET['export']??'';$q=$db->prepare("SELECT s.*,t.table_number,COALESCE(p.name,s.player_name_walkin,'Walk-in Guest') player_name,u.name operator_name FROM sessions s JOIN tables t ON t.id=s.table_id JOIN users u ON u.id=s.operator_id LEFT JOIN players p ON p.id=s.player_id WHERE s.club_id=? AND s.status='completed' AND DATE(s.end_time) BETWEEN ? AND ? ORDER BY s.end_time DESC LIMIT 500");$q->execute([$club,$from,$to]);$rows=$q->fetchAll();if($export==='csv'){header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="cuepos-sessions-'.$from.'-'.$to.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Date','Table','Player','Start','End','Mode','Table','Cafe','Discount','Total','Payment','Operator']);foreach($rows as $s)fputcsv($o,[$s['end_time'],$s['table_number'],$s['player_name'],$s['start_time'],$s['end_time'],$s['billing_type'],$s['table_amount'],$s['cafe_amount'],$s['discount_amount'],$s['total_amount'],$s['payment_method'],$s['operator_name']]);exit;}?><h1 class="text-2xl font-bold">Session History</h1><form class="card mt-5 flex flex-wrap gap-3 items-end"><div><label class="label">From</label><input class="input" type="date" name="from" value="<?=$from?>"></div><div><label class="label">To</label><input class="input" type="date" name="to" value="<?=$to?>"></div><button class="btn-secondary">Filter</button><a class="btn-primary" href="?from=<?=$from?>&to=<?=$to?>&export=csv"><i class="fa-solid fa-file-csv mr-1"></i>Export CSV</a><a class="btn-secondary" href="<?=url('modules/export_sessions_pdf.php?from='.$from.'&to='.$to)?>"><i class="fa-solid fa-file-pdf mr-1"></i>Export PDF</a></form><section class="card mt-5 overflow-x-auto"><table class="data-table w-full"><thead><tr><th>Date</th><th>Table</th><th>Player</th><th>Duration</th><th>Mode</th><th>Table</th><th>Café</th><th>Discount</th><th>Total</th><th>Payment</th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><?=date('d M Y H:i',strtotime($s['end_time']))?></td><td><?=$s['table_number']?></td><td><?=sanitize($s['player_name'])?></td><td><?=gmdate('H:i',max(0,strtotime($s['end_time'])-strtotime($s['start_time'])-$s['total_pause_seconds']))?></td><td><?=sanitize($s['billing_type'])?></td><td><?=money($s['table_amount'])?></td><td><?=money($s['cafe_amount'])?></td><td><?=money($s['discount_amount'])?></td><td class="font-bold text-green-400"><?=money($s['total_amount'])?></td><td><?=sanitize($s['payment_method'])?></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
